update_rule.pseudocode:
if day in campaign_schedule:
  for each person i:
    exposure_prob = sum(media.reach for media in i.information_sources) * media_message_frequency
    if Bernoulli(exposure_prob):
      net_valence = sum(media.credibility*(1 - media.misinformation_rate)*media.message_valence + media.misinformation_rate*(-abs(media.message_valence)) for media in i.information_sources)
      i.trust_in_authorities = clip(Normal(i.trust_in_authorities, trust_in_authorities_std) + campaign_effect_size*net_valence, 0, 1)
      i.risk_perception = clip(i.risk_perception + campaign_effect_size*net_valence, 0, 1)
      i.mask_attitude = clip(i.mask_attitude + 0.5*campaign_effect_size*net_valence, 0, 1)
else:
  for each person i, with probability media_message_frequency*reach:
    apply smaller update: risk_perception += 0.25*campaign_effect_size*(message_valence - misinformation_effect)
    trust_in_authorities regresses slightly toward trust_in_authorities_mean

noncompliance_events = 0
for each person i:
  # sample visited locations by mix
  visits = sample_types_by_prob({home: location_mix_home, work: location_mix_work, school: location_mix_school, retail: location_mix_retail, transit: location_mix_transit})
  for each visit v:
    L = choose_location_of_type(v)
    if L.policy_requirement == 'mask' or global policy_state == 'mandate':
      if i.mask_wearing == false:
        enforce_prob = clip(L.enforcement_signal * (1 - location_enforcement_noise), 0, 1)
        if Bernoulli(enforce_prob):
          noncompliance_events += 1
          if Bernoulli(policy_access_denial_rate): deny entry; else allow with penalty Bernoulli(noncompliance_penalty_probability)
    L.foot_traffic += 1
